mapper.select:
SELECT p.id AS pointId, p.point_code AS pointCode, p.point_name AS pointName, p.tunnel_id AS tunnelId, t.tunnel_name AS tunnelName, p.section_id AS sectionId, p.hazard_type AS hazardType, p.item_type AS itemType, p.unit, l.value, l.ts, l.quality, p.online_status AS onlineStatus, we.warn_level AS warnLevel FROM mon_point p JOIN prj_tunnel t ON t.id = p.tunnel_id AND t.is_deleted = 0 LEFT JOIN data_point_latest l ON l.point_id = p.id LEFT JOIN ( SELECT point_id, MAX(warn_level) AS warn_level FROM warn_event WHERE warn_status IN (1, 2, 3, 4) GROUP BY point_id ) we ON we.point_id = p.id WHERE p.is_deleted = 0 AND p.enabled = 1 AND p.tunnel_id = #{tunnelId} AND p.section_id = #{sectionId} AND p.hazard_type = #{hazardType}
AND (p.point_code LIKE CONCAT('%', #{keyword}, '%') OR p.point_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.id

SELECT ts, value, quality
FROM data_sample
WHERE point_id = #{pointId} AND ts >= #{fromTs} AND ts <= #{toTs}
ORDER BY ts ASC
LIMIT #{limit}

SELECT MAX(value) AS max, MIN(value) AS min, AVG(value) AS avg
FROM data_sample
WHERE point_id = #{pointId} AND ts >= #{fromTs} AND ts <= #{toTs}
